package com.aadil.ecommerce.dtos;import jakarta.validation.constraints.*;import lombok.Data;@Datapublic class UserRequestDTO {    @NotBlank(message = "Name must not be BLANK")    @Size(max = 50)    private String name;    @Email(message = "Email must be formatted in lowercase")    @NotBlank(message = "Email must not be NULL")    private String email;    @Pattern(regexp = "^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).+$", message = "Password must contain at least one lowercase letter, one uppercase letter, and one digit")    @NotBlank(message = "Password field should NOT be BLANK")     private String password;}